// optional on the constructor because callers derive it from an API response that may not
// carry one — the base retail-react-app PDP passes a possibly-undefined status through.
declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/errors' {
  export class HTTPError extends Error {
    constructor(status?: number, message?: string);
    status?: number;
    toString(): string;
  }

  export class HTTPNotFound extends HTTPError {
    constructor(message?: string);
  }
}

// Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
declare module '@salesforce/retail-react-app/*';

// @vitejs/plugin-react uses package exports only (no root index.d.ts), which
// TypeScript 4.9 with moduleResolution:node cannot resolve. Minimal shim — the
// actual Plugin return type depends on vite types that are equally unreachable
// from TS 4.9. Once the project upgrades to TS 5+ this declaration can be removed.
declare module '@vitejs/plugin-react' {
  interface Options {
    include?: string | RegExp | Array<string | RegExp>;
    exclude?: string | RegExp | Array<string | RegExp>;
    jsxImportSource?: string;
  }
  // Return typed as any: Plugin from vite is not resolvable under moduleResolution:node.
  function react(options?: Options): any;
  export default react;

