  const updatedUrl = rebuildPathWithParams(`${location.pathname}${location.search}`, {
    pid: variant?.productId,
  });
  history.replace(updatedUrl);
}, [variant]);

/**************** Wishlist ****************/
const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');

const handleAddToWishlist = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
  const isItemInWishlist = wishlist?.customerProductListItems?.find(
    (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
  );

  if (!isItemInWishlist) {
    createCustomerProductListItem.mutate(
      {
        parameters: {
          listId: wishlist.id,
          // SDK param widening — `useCustomerId` returns `string | null`; this branch is
          // only reachable once a wishlist has loaded, which requires a customer.
          customerId: customerId as string,
        },
        body: {
          // NOTE: API does not respect quantity, it always adds 1
          quantity,
          productId: variant?.productId || product?.id,
          public: false,
          priority: 1,
          type: 'product',
        },
      },
      {
        onSuccess: () => {
          toast({
            title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
            status: 'success',
            action: (
              // it would be better if we could use <Button as={Link}>
              // but unfortunately the Link component is not compatible
              // with Chakra Toast, since the ToastManager is rendered via portal
              // and the toast doesn't have access to intl provider, which is a
              // requirement of the Link component.
              <Button variant="link" onClick={() => navigate('/account/wishlist')}>
                {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
              </Button>
            ),
          });
        },
        onError: () => {
          showError();
        },
      },
    );
  } else {
    toast({
      title: formatMessage(TOAST_MESSAGE_ALREADY_IN_WISHLIST),
      status: 'info',
      action: (
        <Button variant="link" onClick={() => navigate('/account/wishlist')}>
          {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
        </Button>
      ),
    });

